def factorial(n):
    if n < 0:
        raise ValueError('n must be non-negative')
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def is_palindrome(s):
    cleaned = ''.join(ch.lower() for ch in s if ch.isalnum())
    return cleaned == cleaned[::-1]

def two_largest(nums):
    if len(nums) < 2:
        raise ValueError('need at least two values')
    first = second = float('-inf')
    for value in nums:
        if value > first:
            first, second = value, first
        elif value > second:
            second = value
    return first, second

from collections import Counter


def word_counts(text):
    return Counter(text.lower().split())

def flatten(items):
    out = []
    for item in items:
        if isinstance(item, list):
            out.extend(flatten(item))
        else:
            out.append(item)
    return out

def merge_sorted(a, b):
    result = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    result.extend(a[i:])
    result.extend(b[j:])
    return result

import re

EMAIL = re.compile(r'^[^@\s]+@[^@\s]+\.[^@\s]+$')


def is_email(value):
    return bool(EMAIL.match(value))

def partition(items, predicate):
    yes, no = [], []
    for item in items:
        (yes if predicate(item) else no).append(item)
    return yes, no
